using AirlineBooking.Domain.Common;
using AirlineBooking.Domain.Enums;

namespace AirlineBooking.Domain.Entities;

public class Booking : BaseEntity
{
    /// <summary>
    /// 6-character alphanumeric locator (like a real airline PNR, e.g. "K3F7QX") - the
    /// public-facing identifier callers use to look up a booking, instead of exposing the
    /// internal identity column. Generated by the application layer, not the database, so we
    /// can control the alphabet (no ambiguous 0/O, 1/I) and retry on collision.
    /// </summary>
    public string BookingReference { get; set; } = string.Empty;

    public int PassengerId { get; set; }
    public Passenger Passenger { get; set; } = null!;

    public int FlightId { get; set; }
    public Flight Flight { get; set; } = null!;

    public int SeatId { get; set; }
    public Seat Seat { get; set; } = null!;

    public int FareClassId { get; set; }
    public FareClass FareClass { get; set; } = null!;

    public BookingStatus Status { get; set; } = BookingStatus.Held;

    /// <summary>Price at the moment of booking, snapshotted so later fare/multiplier changes
    /// don't retroactively change what a passenger already agreed to pay.</summary>
    public decimal FareAmount { get; set; }

    /// <summary>Set when Status = Held; a background sweep expires holds past this point.
    /// Null once Confirmed or Cancelled.</summary>
    public DateTime? HeldUntilUtc { get; set; }

    public DateTime? ConfirmedUtc { get; set; }
    public DateTime? CancelledUtc { get; set; }
}
